import React,{useState} from 'react'
import Input from '../../Components/Input/Input';
import SelectFilter from '../../Components/SelectFilter/SelectFilter';
import { ModalBoxStyle } from '../../Utils/constants';
import Box from "@mui/material/Box";
import Button from '../../Components/Button/Button';
import usePostRequest from '../../Hooks/usePostRequest';
// import SelectFilter from "../../../Components/SelectFilter/SelectFilter";
// import Button from "../../../Components/Button/Button";
// import Input from "./../../../Components/Input/Input";
// import NewTripContext from "../NewTripContext";
// import debounce from "lodash.debounce";
// import usePostRequest from "../../../Hooks/usePostRequest";
function DriverForm({handleClose}) {
    const [firstName, setFirstName] = useState("")
    const [lastName, setLastName] = useState("")
    const [identityDocument, setIdentityDocument] = useState("")
    const [password, setPassword] = useState("")
    const [phone, setPhone] = useState("")
    const [email, setEmail] = useState("")
    const [plateNumber, setPlateNumber] = useState("")

    const [createDriver] = usePostRequest(
        `${process.env.REACT_APP_TERA_URL + "back-office/driver/create"}`,
        // setDriversList,
        {
            first_name:firstName,
            last_name:lastName,
            identity_document:identityDocument,
            password:password,
            phone:phone,
            email:email,
            plate_number:plateNumber
        },
        (data) => {
          console.log(data);
        //   getTripList();
          handleClose();
        }
      );

  return (
    <div><Box sx={ModalBoxStyle}>
   <div
      className="flex flex-col justify-between p-4"
      style={{ minHeight: "45vh" }}
    >
      <label className="text-3xl font-extrabold pt-4">Nuevo Conductor</label>
      <div className="flex flex-col gap-2">
        <Input
          label="Nombres"
          placeholder="Nestor"
          value={firstName}
          onChange={(e) => setFirstName(e.target.value)}
        />
       <Input
          label="Apellidos"
          placeholder="Melendez Venancino"
          value={lastName}
          onChange={(e) => setLastName(e.target.value)}
        />
         <Input
          label="DNI"
          placeholder="48521433"
          value={identityDocument}
          onChange={(e) => {
            setPassword(e.target.value)
            setIdentityDocument(e.target.value)}}
        />
         <Input
          label="Contraseña"
          placeholder="48521433"
          value={password}
          onChange={(e) => {
            setPassword(e.target.value)}}
        />
        <Input
          label="Celular"
          placeholder="961506021"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
        />
        <Input
          label="Correo"
          placeholder="nersix_14@hotmail.com"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <Input
          label="Placa"
          placeholder="XYZ123"
          value={plateNumber}
          onChange={(e) => setPlateNumber(e.target.value)}
        />
     
        {/* <Input label="Precio" value={price?.price} style={"disabled"} /> */}
        <div className="grid grid-cols-2 gap-2 mt-4">
          <Button
            text="Cancelar"
            design={"cancel"}
            onClick={() => {
              handleClose();
            }}
          />
          <Button
            text="Registrar"
            // design={isPriceCalculated ? "success" : "disabled"}
            design={"success"}
            onClick={() => {
                createDriver()
            //   setValue(3);

            }}
          />
        </div>
      </div>
    </div>
  </Box></div>
  )
}

export default DriverForm